// Isolated custody contract. No production custodian or independently protected head is configured here.
import {createHash} from 'node:crypto'
import {createIncarnationBoundTransport} from './sourceIncarnation.mjs'
const uid=/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/
const hash=/^[0-9a-f]{64}$/
const deny=()=>{throw Error('mip_registration_custody_required')}
const keys=['version','sequence','previous','source','stream','bindingId','incarnationId','recoveryEvidence']
function snapshot(value,fields){
 if(!value||Object.getPrototypeOf(value)!==Object.prototype||Reflect.ownKeys(value).length!==fields.length)deny()
 const result={}
 for(const key of fields){
  const d=Object.getOwnPropertyDescriptor(value,key)
  if(!d||!('value' in d)||!['string','number'].includes(typeof d.value))deny()
  result[key]=d.value
 }
 return Object.freeze(result)
}
export function registrationEnvelope(value){
 const e=snapshot(value,keys)
 if(e.version!==1||!Number.isSafeInteger(e.sequence)||e.sequence<1||
  !['source','stream','bindingId','incarnationId'].every(k=>uid.test(e[k]))||
  !hash.test(e.recoveryEvidence)||(e.sequence===1?e.previous!=='':!hash.test(e.previous)))deny()
 return e
}
export function registrationDigest(value){
 return createHash('sha256').update(JSON.stringify(registrationEnvelope(value))).digest('hex')
}
const scope=e=>Object.freeze({source:e.source,stream:e.stream,bindingId:e.bindingId,incarnationId:e.incarnationId})
const same=(a,b)=>JSON.stringify(a)===JSON.stringify(b)
async function exact(tx,e){
 const digest=registrationDigest(e)
 if(await tx.head(e.source)!==digest)deny()
 const read=await tx.read(digest)
 if(!read||!same(registrationEnvelope(read),e))deny()
 return digest
}
// withAuthority must authenticate its caller and hold source-scoped exclusion against
// registration/recovery/revocation until the awaited callback completes. A precheck is insufficient.
// append must be append-only and crash durable before resolving; read must bypass caches.
export async function retainRegistration({envelope,withAuthority}={}){
 const e=registrationEnvelope(envelope),digest=registrationDigest(e)
 if(typeof withAuthority!=='function')deny()
 return withAuthority(Object.freeze({...scope(e),operation:'register',digest,envelope:e}),async tx=>{
  const head=await tx.head(e.source)
  if(head===digest){await exact(tx,e);return digest}
  if((head??'')!==e.previous)deny()
  if(e.sequence>1){
   const old=registrationEnvelope(await tx.read(e.previous))
   if(registrationDigest(old)!==e.previous||old.source!==e.source||
    old.sequence+1!==e.sequence||old.incarnationId===e.incarnationId||
    old.bindingId===e.bindingId)deny()
  }
  await tx.append(digest,e,e.previous)
  await exact(tx,e)
  return digest
 })
}
export function createCustodyBoundTransport({envelope,expectedHead,withAuthority,call}={}){
 const e=registrationEnvelope(envelope)
 if(expectedHead!==registrationDigest(e)||typeof withAuthority!=='function')deny()
 const transport=createIncarnationBoundTransport({incarnationId:e.incarnationId,call})
 const run=(method,p,fields)=> {
  // Capture primitive values synchronously, before any authority or storage await.
  const input=snapshot(p,fields)
  if(('bindingId' in input&&input.bindingId!==e.bindingId)||
   ('source' in input&&input.source!==e.source)||('stream' in input&&input.stream!==e.stream))deny()
  return withAuthority(Object.freeze({...scope(e),operation:method,digest:expectedHead}),async tx=>{
   await exact(tx,e)
   // The trusted journal binds preparation requests durably before any source effect.
   // Old or ambiguous request bindings cannot be adopted from a restored source.
   const requestScope=Object.freeze({...scope(e),digest:expectedHead})
   if(method==='prepare'){
    await tx.bindRequest(input.request,requestScope)
    if(!same(await tx.readRequest(input.request),requestScope))deny()
   }
   if(method==='advance'&&!same(await tx.readRequest(input.request),requestScope))deny()
   return transport[method](input)
  })
 }
 return Object.freeze({
  capture:p=>run('capture',p,['session','bindingId','before','request']),
  prepare:p=>run('prepare',p,['session','bindingId','source','stream','request','end','hash','capture','bootstrap','frames']),
  advance:p=>run('advance',p,['session','request'])
 })
}

// Filesystem fixture executes on GitHub-hosted CI only. It is not a production custodian.
import test from 'node:test'
import assert from 'node:assert/strict'
import {mkdtemp,open,readFile,rm} from 'node:fs/promises'
import {tmpdir} from 'node:os'
import {join} from 'node:path'
import {registrationEnvelope,registrationDigest,retainRegistration,createCustodyBoundTransport} from '../supabase/qualification/hypothesis-assessments/registrationCustody.mjs'
const id=n=>String(n).repeat(8)+'-'+String(n).repeat(4)+'-4'+String(n).repeat(3)+'-8'+String(n).repeat(3)+'-'+String(n).repeat(12)
const e=()=>({version:1,sequence:1,previous:'',source:id(1),stream:id(2),bindingId:id(3),incarnationId:id(4),recoveryEvidence:'a'.repeat(64)})
const capture=()=>({session:id(5),bindingId:id(3),before:'0/10',request:id(6)})
const prepare=()=>({...capture(),source:id(1),stream:id(2),end:'0/20',hash:'b'.repeat(64),capture:id(7),bootstrap:'c'.repeat(64),frames:'d'.repeat(64)})
function preparation(){const p=prepare();delete p.before;return p}
const gate={skip:process.env.GITHUB_ACTIONS!=='true'}
async function fixture(t){
 const dir=await mkdtemp(join(tmpdir(),'mip-custody-ci-'))
 t.after(()=>rm(dir,{recursive:true,force:true}))
 const file=join(dir,'external-journal.jsonl')
 let queue=Promise.resolve(),authorized=true
 const load=async()=>{try{return (await readFile(file,'utf8')).trim().split('\n').filter(Boolean).map(JSON.parse)}catch(err){if(err.code==='ENOENT')return [];throw err}}
 const append=async row=>{
  const f=await open(file,'a',0o600)
  try{await f.writeFile(JSON.stringify(row)+'\n');await f.sync()}finally{await f.close()}
  const d=await open(dir,'r');try{await d.sync()}finally{await d.close()}
 }
 const exclusive=fn=>{const next=queue.then(fn);queue=next.catch(()=>{});return next}
 const withAuthority=(scope,fn)=>exclusive(async()=>{
  if(!authorized)throw Error('revoked')
  const rows=await load()
  const tx={
   head:async source=>rows.filter(r=>r.kind==='registration'&&r.envelope.source===source).at(-1)?.digest??null,
   read:async digest=>rows.find(r=>r.kind==='registration'&&r.digest===digest)?.envelope,
   append:async(digest,envelope,previous)=>{
    if((await tx.head(envelope.source)??'')!==previous)throw Error('stale')
    const row={kind:'registration',digest,envelope};await append(row);rows.push(row)
   },
   bindRequest:async(request,scope)=>{
    const existing=await tx.readRequest(request)
    if(existing){assert.deepEqual(existing,scope);return}
    const row={kind:'request',request,scope};await append(row);rows.push(row)
   },
   readRequest:async request=>rows.find(r=>r.kind==='request'&&r.request===request)?.scope
  }
  // Independently read the durable bytes, not the just-written in-memory row.
  const read=tx.read;tx.read=async digest=>(await load()).find(r=>r.kind==='registration'&&r.digest===digest)?.envelope
  tx.readRequest=async request=>(await load()).find(r=>r.kind==='request'&&r.request===request)?.scope
  return fn(tx)
 })
 return {snapshot:()=>readFile(file,'utf8'),restore:async bytes=>{const f=await open(file,'w');try{await f.writeFile(bytes);await f.sync()}finally{await f.close()}},withAuthority,revoke:()=>exclusive(()=>{authorized=false}),load,
  transport:(envelope=e(),call=async()=>true)=>createCustodyBoundTransport({envelope,expectedHead:registrationDigest(envelope),withAuthority,call})}
}
test('envelopes reject missing, malformed, accessors, extra fields and automatic source pins',()=>{
 for(const value of [{}, {...e(),sequence:0},{...e(),previous:'bad'},{...e(),auto:true},{...e(),source:'auto'}])
  assert.throws(()=>registrationEnvelope(value),/custody/)
 const value=e();Object.defineProperty(value,'source',{get:()=>id(1)})
 assert.throws(()=>registrationEnvelope(value),/custody/)
 assert.throws(()=>createCustodyBoundTransport({envelope:e(),expectedHead:'f'.repeat(64),withAuthority:()=>{},call:()=>{}}),/custody/)
})
test('durable exact registration replay, restart reconstruction and request continuity',gate,async t=>{
 const f=await fixture(t),envelope=e()
 const digest=await retainRegistration({envelope,withAuthority:f.withAuthority})
 assert.equal(digest,registrationDigest(envelope))
 assert.equal(await retainRegistration({envelope,withAuthority:f.withAuthority}),digest)
 assert.equal((await f.load()).length,1)
 await f.transport().prepare(preparation())
 // Reconstruct a transport: only durable journal bytes supply request/head state.
 assert.equal(await f.transport().advance({session:id(5),request:id(6)}),true)
})
test('recovery requires exact predecessor, new incarnation/binding and current head',gate,async t=>{
 const f=await fixture(t),first=e()
 await retainRegistration({envelope:first,withAuthority:f.withAuthority})
 const next={...first,sequence:2,previous:registrationDigest(first),bindingId:id(8),incarnationId:id(9)}
 for(const bad of [{...next,previous:'f'.repeat(64)},{...next,sequence:3},{...next,bindingId:first.bindingId},{...next,incarnationId:first.incarnationId}])
  await assert.rejects(()=>retainRegistration({envelope:bad,withAuthority:f.withAuthority}),/custody/)
 await retainRegistration({envelope:next,withAuthority:f.withAuthority})
 await assert.rejects(()=>retainRegistration({envelope:first,withAuthority:f.withAuthority}),/custody/)
 await assert.rejects(()=>f.transport().capture(capture()),/custody/)
 await assert.rejects(()=>retainRegistration({envelope:{...next,recoveryEvidence:'f'.repeat(64)},withAuthority:f.withAuthority}),/custody/)
})
test('missing predecessor record or changed durable readback is denied',async()=>{
 const first=e(),next={...e(),sequence:2,previous:registrationDigest(first),bindingId:id(8),incarnationId:id(9)}
 await assert.rejects(()=>retainRegistration({envelope:next,withAuthority:async(_,fn)=>fn({head:async()=>next.previous,read:async()=>undefined})}),/custody/)
 let called=0
 const transport=createCustodyBoundTransport({envelope:first,expectedHead:registrationDigest(first),call:async()=>{called++},
  withAuthority:async(_,fn)=>fn({head:async()=>registrationDigest(first),read:async()=>({...first,recoveryEvidence:'f'.repeat(64)})})})
 await assert.rejects(()=>transport.capture(capture()),/custody/)
 assert.equal(called,0)
})
test('scope mismatch and unretained advancement fail before a source call',gate,async t=>{
 const f=await fixture(t);await retainRegistration({envelope:e(),withAuthority:f.withAuthority})
 let calls=0;const tr=f.transport(e(),async()=>{calls++})
 assert.throws(()=>tr.capture({...capture(),bindingId:id(9)}),/custody/)
 assert.throws(()=>tr.prepare({...preparation(),source:id(9)}),/custody/)
 assert.throws(()=>tr.prepare({...preparation(),stream:id(9)}),/custody/)
 await assert.rejects(()=>tr.advance({session:id(5),request:id(6)}),/custody/)
 assert.equal(calls,0)
})
test('authority excludes revocation through source completion and freezes inputs before awaits',gate,async t=>{
 const f=await fixture(t);await retainRegistration({envelope:e(),withAuthority:f.withAuthority})
 let enter,release;const entered=new Promise(r=>enter=r),pending=new Promise(r=>release=r)
 let actual
 const tr=f.transport(e(),async(name,args)=>{actual={name,args};enter();await pending;return true})
 const p=capture(),operation=tr.capture(p);p.request=id(9)
 await entered
 let revoked=false;const revocation=f.revoke().then(()=>{revoked=true})
 await Promise.resolve();assert.equal(revoked,false)
 release();assert.equal(await operation,true);await revocation
 assert.equal(actual.args.at(-1),id(6))
 await assert.rejects(()=>tr.capture(capture()),/revoked/)
})
test('actual ledger rollback is denied by retained newer envelope; co-restored pin cannot be detected',gate,async t=>{
 const f=await fixture(t);await retainRegistration({envelope:e(),withAuthority:f.withAuthority})
 const oldBytes=await f.snapshot()
 const newer={...e(),sequence:2,previous:registrationDigest(e()),bindingId:id(8),incarnationId:id(9)}
 await retainRegistration({envelope:newer,withAuthority:f.withAuthority})
 const pinned=f.transport(newer)
 const newCapture={...capture(),bindingId:id(8)}
 assert.equal(await pinned.capture(newCapture),true)
 await f.restore(oldBytes)
 await assert.rejects(()=>pinned.capture(newCapture),/custody/)
 // If the separately held expected envelope/head is ALSO rolled back, acceptance is possible.
 assert.equal(await f.transport(e()).capture(capture()),true)
})

import {restartRemoteStore} from '../integrated/remoteStoreRestart.mjs'
// Native incarnation guards in the disposable database; registrations and mismatches are synthetic.
import assert from 'node:assert/strict'
import {randomUUID,randomBytes} from 'node:crypto'
import {readFile} from 'node:fs/promises'
import {quote as q,raw,guard,transport as sqlTransport} from '../integrated/transport.mjs'
import {hold,blocked} from './fixture.mjs'
import {createIncarnationBoundTransport} from '../../supabase/qualification/hypothesis-assessments/sourceIncarnation.mjs'
import {producerRole} from '../integrated/fixture.mjs'
import {encryptedRemoteJournal} from '../../supabase/qualification/mip-cutover-authority/brokerSession.js'
import {createCustodyBoundTransport,retainRegistration,registrationDigest} from '../../supabase/qualification/hypothesis-assessments/registrationCustody.mjs'
export async function incarnationCases(t,f,staged){
 await f.admin(await readFile(new URL('../../supabase/qualification/hypothesis-assessments/020_native_source_incarnation.sql',import.meta.url),'utf8'))
 const transport=id=>createIncarnationBoundTransport({incarnationId:id,call:async(name,args)=>{
  if(!['capture_incarnation','prepare_incarnation','advance_incarnation'].includes(name))throw Error('synthetic_rpc_denied')
  const role=name==='advance_incarnation'?'mip_temporal_ack_gateway':'mip_temporal_recorder'
  const result=await f.admin('set session authorization '+role+';select mip_temporal.'+name+'('+args.map(q).join(',')+');')
  return name==='prepare_incarnation'?result:JSON.parse(result)
 }})
 const register=async(b,{field}={})=>{
  const id=randomUUID()
  await f.admin('insert into mip_temporal.source_incarnations select '+q(b.bindingId)+','+q(id)+','+
   (field==='system'?"'synthetic-different-cluster'":'c.system_identifier::text')+','+
   (field==='database'?'0::oid':'d.oid')+','+
   (field==='startup'?"pg_postmaster_start_time()-interval '1 second'":'pg_postmaster_start_time()')+','+
   q('synthetic-native-registration-fixture')+' from pg_control_system() c cross join pg_database d where d.datname=current_database();')
  return id
 }
 const capture=(b,api)=>api.capture({session:b.session(),bindingId:b.bindingId,before:b.before,request:randomUUID()})
 const prepared=async t=>{
  const b=await staged(t),id=await register(b),api=transport(id)
  await b.produce()
  const c=await capture(b,api);let request
  await assert.rejects(()=>b.consume(c,{prepare:api.prepare,advance:async p=>{request=p;throw Error('synthetic_hold_incarnation')}}),/synthetic_hold_incarnation/)
  return {b,id,api,c,request,sql:'select mip_temporal.advance_incarnation('+[request.session,request.request,id].map(q).join(',')+');'}
 }
 await t.test('explicit registration permits covered completion and fresh-session exact receipt replay',async t=>{
  const {b,api,c}=await prepared(t)
  await b.consume(c,{prepare:api.prepare,advance:api.advance})
  assert.equal(await b.confirmed(),c.end_lsn);assert.equal(await b.checkpointCount(),'1')
  await b.refresh()
  await b.consume(c,{prepare:api.prepare,advance:api.advance})
  assert.equal(await b.checkpointCount(),'1')
 })
 await t.test('missing or mismatched external pin denies capture, preparation and receipt replay',async t=>{
  const b=await staged(t),missing=transport(randomUUID())
  await assert.rejects(()=>capture(b,missing),/mip_source_incarnation_denied/)
  const id=await register(b),api=transport(id);await b.produce()
  await assert.rejects(()=>capture(b,missing),/mip_source_incarnation_denied/)
  const c=await capture(b,api)
  await assert.rejects(()=>b.consume(c,{prepare:missing.prepare,advance:api.advance}),/mip_source_incarnation_denied/)
  let request
  await assert.rejects(()=>b.consume(c,{prepare:api.prepare,advance:async p=>{request=p;throw Error('synthetic_hold_incarnation')}}),/synthetic_hold_incarnation/)
  await assert.rejects(()=>missing.advance(request),/mip_source_incarnation_denied/)
  assert.equal(await b.confirmed(),b.before)
  await b.consume(c,{prepare:api.prepare,advance:api.advance})
  await assert.rejects(()=>missing.advance(request),/mip_source_incarnation_denied/)
  assert.equal(await b.checkpointCount(),'1')
 })
 await t.test('simulated cluster, database-object and startup mismatches deny native capture without rewriting history',async t=>{
  for(const field of ['system','database','startup']){
   const b=await staged(t),id=await register(b,{field}),api=transport(id)
   await assert.rejects(()=>capture(b,api),/mip_source_native_identity_changed/)
   assert.equal(await b.confirmed(),b.before)
   assert.equal(await f.admin('select count(*) from mip_temporal.source_incarnations where binding_id='+q(b.bindingId)),'1')
   assert.equal(await b.checkpointCount(),'0')
  }
 })
 await t.test('registration is immutable and gateways cannot inspect control data or bypass the incarnation interface',async t=>{
  const b=await staged(t),id=await register(b)
  for(const role of ['mip_temporal_recorder','mip_temporal_ack_gateway','mip_comparison_worker_v1','service_role']){
   await assert.rejects(()=>f.admin('set session authorization '+role+';select * from mip_temporal.source_incarnations;'),/mip_database_denied_42501/)
   await assert.rejects(()=>f.admin('set session authorization '+role+';select * from pg_control_system();'),/mip_database_denied_42501/)
  }
  await assert.rejects(()=>f.admin('update mip_temporal.source_incarnations set incarnation_id='+q(randomUUID())+' where incarnation_id='+q(id)))
  for(const [role,signature] of [
   ['mip_temporal_recorder','mip_temporal.capture_next(uuid,uuid,pg_lsn,uuid)'],
   ['mip_temporal_recorder','mip_temporal.prepare_covered_advance(uuid,uuid,uuid,uuid,uuid,pg_lsn,text,text,text)'],
   ['mip_temporal_ack_gateway','mip_temporal.advance_covered(uuid,uuid)']])
   assert.equal(await f.admin('select has_function_privilege('+[role,signature,'EXECUTE'].map(q).join(',')+')'),'f')
  assert.equal(await f.admin("select rolcanlogin or rolsuper or rolbypassrls from pg_roles where rolname='mip_temporal_registry_owner'"),'f')
  assert.equal(await f.admin("select relrowsecurity and relforcerowsecurity from pg_class where oid='mip_temporal.source_incarnations'::regclass"),'t')
 })
 await t.test('incarnation-bound advancement locks first and source revocation waits',async t=>{
  const {b,api,c,request,sql}=await prepared(t)
  const held=await hold(f.db,sql,'mip_temporal_ack_gateway');let finished=false
  const pending=f.admin(b.revokeSql);pending.catch(()=>{})
  try{
   await blocked(f,held.pid);await held.finish(true);finished=true;await pending
   assert.equal(await b.confirmed(),c.end_lsn);assert.equal(await b.checkpointCount(),'1')
   await assert.rejects(()=>api.advance(request),/mip_temporal_binding_denied/)
  }finally{if(!finished)await held.finish(false)}
 })
 await t.test('source revocation locks first and incarnation-bound advancement rejects without a checkpoint',async t=>{
  const {b,api,request}=await prepared(t)
  const held=await hold(f.db,b.revokeSql);let finished=false
  const pending=api.advance(request);pending.catch(()=>{})
  try{
   await blocked(f,held.pid);await held.finish(true);finished=true
   await assert.rejects(pending,/mip_temporal_binding_denied/)
   assert.equal(await b.confirmed(),b.before);assert.equal(await b.checkpointCount(),'0')
   assert.equal(await f.admin('select count(*) from mip_temporal.covered_permits where request_id='+q(request.request)),'1')
  }finally{if(!finished)await held.finish(false)}
 })

 await t.test('external encrypted custody gates the actual incarnation capture, prepare and advance flow',async t=>{
  const b=await staged(t),incarnationId=await register(b)
  const runtime='synthetic-registration-custody-'+randomUUID(),mapping=randomUUID()
  await f.admin('insert into mip_identity.mapping_versions select '+q(mapping)+','+q(runtime)+
   ',principal,issuer,audience,'+q(runtime+':'+producerRole)+',key_revision,max_lifetime_seconds,approval_ref from mip_identity.mapping_versions where revision='+
   q(f.mappings['runtime-a'+producerRole])+';insert into mip_identity.mapping_heads values('+[runtime,producerRole,mapping].map(q).join(',')+',true);')
  const material={version:'synthetic-custody-v1',key:randomBytes(32)},session=await f.issue(runtime,producerRole)
  const journal=encryptedRemoteJournal({sql:sqlTransport(f.db,'mip_journal_gateway_v2'),session,
   keyProvider:r=>{if(r!==runtime)throw Error('synthetic_wrong_custodian');return material}})
  const envelope={version:1,sequence:1,previous:'',source:b.context.source_id,stream:b.context.stream_epoch,
   bindingId:b.bindingId,incarnationId,recoveryEvidence:'a'.repeat(64)}
  const approved=new Set([registrationDigest(envelope)])
  let failAfterEnvelope=true
  // Test custodian: separate authenticated runtime/key, but same physical PostgreSQL restore domain.
  // Advisory exclusion is shared by this adapter's calls; mapping/key row locks fence real revocation.
  const withAuthority=async(scope,fn)=>{
   if(scope.source!==envelope.source||!approved.has(scope.digest))throw Error('synthetic_custody_not_admitted')
   if(scope.operation==='register'&&registrationDigest(scope.envelope)!==scope.digest)throw Error('synthetic_recovery_not_admitted')
   const held=await hold(f.db,'select pg_advisory_xact_lock(hashtextextended('+q('custody:'+envelope.source)+',0));'+
    'select 1 from mip_identity.fence where id for share;select 1 from mip_identity.mapping_heads where runtime='+q(runtime)+' for share;select 1 from mip_identity.key_heads for share;')
   try{
    const index=n=>'registration-sequence:'+envelope.source+':'+n
    const tx={
     head:async source=>{
      assert.equal(source,envelope.source);let head=null
      for(let n=1;n<=32;n++){const row=await journal.get(index(n));if(!row)return head;head=row.digest}
      throw Error('synthetic_custody_bound_exceeded')
     },
     read:digest=>journal.get('registration:'+digest),
     append:async(digest,value,previous)=>{
      assert.equal((await tx.head(value.source))??'',previous)
      assert.equal((await journal.putOnce('registration:'+digest,value)).committed,true)
      if(failAfterEnvelope){failAfterEnvelope=false;throw Error('synthetic_after_envelope_before_index')}
      assert.equal((await journal.putOnce(index(value.sequence),{digest})).committed,true)
     },
     bindRequest:async(request,value)=>{assert.equal((await journal.putOnce('registration-request:'+request,value)).committed,true)},
     readRequest:request=>journal.get('registration-request:'+request)
    }
    return await fn(tx)
   }finally{await held.finish(true)}
  }
  await assert.rejects(()=>retainRegistration({envelope,withAuthority}),/synthetic_after_envelope_before_index/)
  assert.deepEqual(await journal.get('registration:'+registrationDigest(envelope)),envelope)
  assert.equal(await journal.get('registration-sequence:'+envelope.source+':1'),null)
  await retainRegistration({envelope,withAuthority})
  const baseApi=transport(incarnationId)
  const call=(name,args)=>name==='capture_incarnation'?baseApi.capture({session:args[0],bindingId:args[1],before:args[3],request:args[4]}):
